<?php
require '../config/database.php'; require '../includes/functions.php'; require_staff();
$stats=['pending'=>(int)$pdo->query("SELECT COUNT(*) FROM bookings WHERE status='pending'")->fetchColumn(),'confirmed'=>(int)$pdo->query("SELECT COUNT(*) FROM bookings WHERE status='confirmed'")->fetchColumn(),'available'=>(int)$pdo->query("SELECT COUNT(*) FROM rooms r WHERE r.status='available' AND NOT EXISTS (SELECT 1 FROM bookings b WHERE b.room_id=r.id AND b.status IN ('pending','confirmed') AND b.check_in < DATE_ADD(CURDATE(), INTERVAL 1 DAY) AND b.check_out > CURDATE())")->fetchColumn(),'today'=>(int)$pdo->query("SELECT COUNT(*) FROM bookings WHERE check_in=CURDATE() AND status='confirmed'")->fetchColumn()];
$pending=$pdo->query("SELECT b.*,u.name guest,u.email,r.name room_name,r.room_type FROM bookings b JOIN users u ON u.id=b.user_id JOIN rooms r ON r.id=b.room_id WHERE b.status='pending' ORDER BY b.created_at ASC LIMIT 8")->fetchAll();
$activeGuests=$pdo->query("SELECT b.id,b.reference_no,b.check_out,b.guests,u.name guest,u.email,r.name room_name FROM bookings b JOIN users u ON u.id=b.user_id JOIN rooms r ON r.id=b.room_id WHERE b.status='confirmed' AND b.check_in<=CURDATE() AND b.check_out>CURDATE() ORDER BY b.check_out ASC")->fetchAll();
$rooms=$pdo->query("SELECT r.id,r.name,r.room_type,r.capacity,r.price_per_night,r.status FROM rooms r WHERE r.status='available' AND NOT EXISTS (SELECT 1 FROM bookings b WHERE b.room_id=r.id AND b.status IN ('pending','confirmed') AND b.check_in < DATE_ADD(CURDATE(), INTERVAL 1 DAY) AND b.check_out > CURDATE()) ORDER BY r.name LIMIT 8")->fetchAll();
$page_title='Reception Overview'; include '../includes/header.php'; ?>
<div class="workspace"><aside class="workspace-sidebar"><div class="side-label">RECEPTION DESK</div><a class="active" href="<?=url('staff/index.php')?>">▦ &nbsp; Overview</a><a href="<?=url('staff/bookings/index.php')?>">✓ &nbsp; Booking approvals <span class="side-count"><?=$stats['pending']?></span></a><a href="#available-rooms">▣ &nbsp; Available rooms</a><div class="sidebar-note"><strong>Receptionist / Staff</strong><p>Review reservation requests and keep track of room availability.</p><small>Room and user management are restricted to administrators.</small></div></aside>
<section class="workspace-main"><div class="workspace-heading"><div><div class="eyebrow" style="color:var(--brand)">FRONT DESK</div><h1>Welcome, <?=e($_SESSION['user']['name'])?></h1><p class="muted">Your daily reception overview and reservation queue.</p></div><a class="btn btn-primary" href="<?=url('staff/bookings/index.php')?>">Review pending bookings →</a></div>
<div class="stats-dashboard staff-metrics"><article class="metric-card"><span class="metric-icon amber">◷</span><span class="metric-label">Awaiting approval</span><strong><?=$stats['pending']?></strong><small>Requests to review</small></article><article class="metric-card"><span class="metric-icon green">✓</span><span class="metric-label">Confirmed bookings</span><strong><?=$stats['confirmed']?></strong><small>Approved reservations</small></article><article class="metric-card"><span class="metric-icon blue">▣</span><span class="metric-label">Available rooms</span><strong><?=$stats['available']?></strong><small>Rooms available for tonight; overlapping pending and confirmed stays are excluded</small></article><article class="metric-card"><span class="metric-icon violet">⇥</span><span class="metric-label">Arriving today</span><strong><?=$stats['today']?></strong><small>Confirmed check-ins</small></article></div>
<section class="panel staff-section"><div class="panel-heading"><div><h2>Current guests</h2><p class="muted">Confirmed guests who are currently checked in, with their room and remaining stay.</p></div><span class="badge confirmed"><?=count($activeGuests)?> staying</span></div><div class="table-wrap clean-table"><table class="table"><thead><tr><th>Guest</th><th>Room</th><th>Check-out</th><th>Days left</th><th>Reservation</th></tr></thead><tbody><?php if(!$activeGuests): ?><tr><td colspan="5" class="empty">No confirmed guests are currently staying.</td></tr><?php endif; foreach($activeGuests as $guest): $daysLeft=(new DateTimeImmutable(date('Y-m-d')))->diff(new DateTimeImmutable($guest['check_out']))->days; ?><tr><td><strong><?=e($guest['guest'])?></strong><small class="table-sub"><?=e($guest['email'])?></small></td><td><?=e($guest['room_name'])?><small class="table-sub"><?=$guest['guests']?> guest(s)</small></td><td><?=e(date('M j, Y',strtotime($guest['check_out'])))?></td><td><strong><?=$daysLeft?> day(s)</strong></td><td><?=e($guest['reference_no'])?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel staff-section"><div class="panel-heading"><div><h2>Booking requests</h2><p class="muted">Approve or decline pending reservations.</p></div><a class="text-link" href="<?=url('staff/bookings/index.php')?>">Open approval queue →</a></div><div class="table-wrap clean-table"><table class="table"><thead><tr><th>Reference</th><th>Guest / Room</th><th>Stay dates</th><th>Total</th><th>Decision</th></tr></thead><tbody><?php if(!$pending): ?><tr><td colspan="5" class="empty">You're all caught up. No pending bookings.</td></tr><?php endif; foreach($pending as $b): ?><tr><td><strong><?=e($b['reference_no'])?></strong><small class="table-sub">Requested <?=e(date('M j, Y',strtotime($b['created_at'])))?></small></td><td><?=e($b['guest'])?><small class="table-sub"><?=e($b['room_name'])?></small></td><td><?=e(date('M j',strtotime($b['check_in'])))?> – <?=e(date('M j, Y',strtotime($b['check_out'])))?></td><td>₱<?=number_format($b['total_amount'],2)?></td><td><div class="actions"><form method="post" action="<?=url('staff/bookings/index.php')?>" data-confirm="Approve this reservation? The system will recheck room availability for the requested dates." data-confirm-title="Approve booking"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$b['id']?>"><input type="hidden" name="decision" value="confirmed"><button class="btn btn-primary btn-sm">Approve</button></form><form method="post" action="<?=url('staff/bookings/index.php')?>" data-confirm="Decline this reservation request?" data-confirm-title="Decline booking"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$b['id']?>"><input type="hidden" name="decision" value="cancelled"><button class="btn btn-outline btn-sm" data-confirm="Decline this booking request?">Decline</button></form></div></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel staff-section" id="available-rooms"><div class="panel-heading"><div><h2>Available rooms</h2><p class="muted">Read-only room status for reception use.</p></div><span class="pill-count"><?=$stats['available']?> available</span></div><div class="room-status-grid"><?php foreach($rooms as $r): ?><article class="room-status-card"><div class="room-status-top"><span class="room-status-icon">▣</span><span class="availability-dot">Available</span></div><h3><?=e($r['name'])?></h3><p class="muted"><?=e($r['room_type'])?> · Up to <?=e($r['capacity'])?> guests</p><strong>₱<?=number_format($r['price_per_night'],2)?> <small>/ night</small></strong></article><?php endforeach; if(!$rooms): ?><p class="empty">No rooms are currently marked available.</p><?php endif; ?></div></section></section></div>
<?php include '../includes/footer.php'; ?>